/**
 * Email receipt fixtures (`fixtures/emails/<emailId>.json`, generated by
 * `fixtures/_gen/emails.mjs`). File shape:
 *
 * ```
 * { fixtureVersion, groupId, tripId, forwardingAddress?, email: InboundEmail, expected: {...} }
 * ```
 *
 * Only `email` (and the owner's `forwardingAddress`) is used by the mock;
 * `expected` is ground truth for tests and evals and is ignored here. Bodies
 * are untrusted text and are stored as-is; nothing in this module reads them.
 */
import { parseIso } from '@trav/core';
import type { EmailAttachment, InboundEmail } from '../../interfaces/emailReceipts.js';
import {
  asArr,
  asObj,
  deepFreeze,
  fixtureFail,
  optStr,
  str,
} from '../transactions/fixtureFiles.js';
import { listFixtures, loadFixture } from '../fixtures.js';

export interface EmailFixture {
  readonly email: InboundEmail;
  /** The owner's private forwarding address this email arrived at, if the fixture names one. */
  readonly forwardingAddress?: string;
  readonly groupId?: string;
  readonly tripId?: string;
}

const ADDRESS_RE = /^[a-z0-9][a-z0-9._+-]{0,63}@[a-z0-9-]+(\.[a-z0-9-]+)+$/;

export function isForwardingAddress(value: string): boolean {
  return ADDRESS_RE.test(value);
}

function checkIso(value: string, where: string): void {
  try {
    parseIso(value);
  } catch {
    fixtureFail(where, `expected ISO date-time with offset, got "${value}"`);
  }
}

function parseAttachment(raw: unknown, where: string): EmailAttachment {
  const o = asObj(raw, where);
  return {
    fileName: str(o, 'fileName', where),
    mimeType: str(o, 'mimeType', where),
    uri: str(o, 'uri', where),
  };
}

/** Validates one raw `InboundEmail` object. */
export function parseInboundEmail(raw: unknown, where = 'email'): InboundEmail {
  const o = asObj(raw, where);
  const receivedAt = str(o, 'receivedAt', where);
  checkIso(receivedAt, `${where}.receivedAt`);
  const textBody = optStr(o, 'textBody', where);
  const htmlBody = optStr(o, 'htmlBody', where);
  const attachments =
    o['attachments'] === undefined ? [] : asArr(o['attachments'], `${where}.attachments`);
  return {
    emailId: str(o, 'emailId', where),
    ownerMemberId: str(o, 'ownerMemberId', where),
    from: str(o, 'from', where),
    subject: optStr(o, 'subject', where) ?? '',
    receivedAt,
    ...(textBody === undefined ? {} : { textBody }),
    ...(htmlBody === undefined ? {} : { htmlBody }),
    attachments: attachments.map((a, i) => parseAttachment(a, `${where}.attachments[${i}]`)),
  };
}

export function parseEmailFixture(raw: unknown, where = 'email fixture'): EmailFixture {
  const o = asObj(raw, where);
  const email = parseInboundEmail(o['email'], `${where}.email`);
  const forwardingAddress = optStr(o, 'forwardingAddress', where)?.toLowerCase();
  if (forwardingAddress !== undefined && !isForwardingAddress(forwardingAddress)) {
    fixtureFail(`${where}.forwardingAddress`, 'not an email address');
  }
  const groupId = optStr(o, 'groupId', where);
  const tripId = optStr(o, 'tripId', where);
  return deepFreeze({
    email,
    ...(forwardingAddress === undefined ? {} : { forwardingAddress }),
    ...(groupId === undefined ? {} : { groupId }),
    ...(tripId === undefined ? {} : { tripId }),
  });
}

/** Loads every `fixtures/<dir...>/*.json` email fixture, sorted by file name. */
export function loadEmailFixtures(dir: readonly string[] = ['emails']): readonly EmailFixture[] {
  return listFixtures(dir).map((name) => {
    const fixture = parseEmailFixture(
      loadFixture(dir, name),
      `fixtures/${dir.join('/')}/${name}.json`,
    );
    if (fixture.email.emailId !== name) {
      fixtureFail(name, `file name does not match emailId ${fixture.email.emailId}`);
    }
    return fixture;
  });
}
